"""Pre-allocation of sink files."""

import os

from .errors import WSParseError
from ._winapi import is_windows


def _check_size(size):
    if isinstance(size, bool) or not isinstance(size, int):
        raise WSParseError("size must be an integer, got %r" % (size,), kind="badarg")
    if size < 0:
        raise WSParseError("size must not be negative, got %r" % (size,), kind="badarg")


def preallocate(path, size):
    """Grow ``path`` to ``size`` bytes and reserve the space for it.

    On Windows/NTFS this marks the file as sparse and extends its logical
    length without allocating disk clusters for the unwritten regions.
    The call is idempotent -- calling it again with the same or smaller
    ``size`` leaves the file untouched.  Existing content is preserved;
    the file is only ever extended, never shrunk.

    Returns the resulting file length in bytes.
    """
    _check_size(size)
    path = os.fspath(path)

    if not is_windows():
        raise WSParseError(
            "preallocate requires Windows/NTFS",
            kind="unsupported",
            path=path,
        )

    from ._winapi import (
        create_file, close_handle, set_sparse,
        set_file_pointer_ex, set_end_of_file,
        GENERIC_READ, GENERIC_WRITE, OPEN_ALWAYS,
    )

    handle = None
    try:
        handle = create_file(path, disposition=OPEN_ALWAYS)
    except OSError as exc:
        raise WSParseError(str(exc), kind="os", path=path) from exc

    try:
        # Mark the file as sparse
        try:
            set_sparse(handle)
        except OSError as exc:
            raise WSParseError(
                "cannot set sparse flag: %s" % exc,
                kind="unsupported",
                path=path,
            ) from exc

        # Get current file size by seeking to end
        current_size = set_file_pointer_ex(handle, 0, move_method=2)  # FILE_END

        if size > current_size:
            # Extend the file: seek to desired size and set end of file
            set_file_pointer_ex(handle, size, move_method=0)  # FILE_BEGIN
            set_end_of_file(handle)

        # Flush to ensure metadata is persisted
        import ctypes
        ctypes.windll.kernel32.FlushFileBuffers(ctypes.c_void_p(handle))

        return max(current_size, size)

    except WSParseError:
        raise
    except OSError as exc:
        raise WSParseError(str(exc), kind="os", path=path) from exc
    finally:
        if handle is not None:
            close_handle(handle)

"""Allocated-range reporting for sink files."""

import os

from .errors import WSParseError
from ._winapi import is_windows


def allocated_ranges(path):
    """Return ``[(offset, length), ...]`` of the byte ranges backed by clusters.

    On Windows/NTFS this queries the file system for the actual allocated
    extents using FSCTL_QUERY_ALLOCATED_RANGES.  For a fully-sparse (empty)
    file the list is empty; for a dense file it covers the entire length.
    The list is ordered by ``offset`` and the ranges never overlap.  Every
    range lies inside the file's logical length.
    """
    path = os.fspath(path)

    if not is_windows():
        raise WSParseError(
            "allocated_ranges requires Windows/NTFS",
            kind="unsupported",
            path=path,
        )

    try:
        size = os.path.getsize(path)
    except OSError as exc:
        raise WSParseError(str(exc), kind="os", path=path) from exc

    if size == 0:
        return []

    # Check if it's a directory
    import stat
    try:
        st = os.stat(path)
    except OSError as exc:
        raise WSParseError(str(exc), kind="os", path=path) from exc

    if stat.S_ISDIR(st.st_mode):
        raise WSParseError(
            "path is a directory, not a file",
            kind="unsupported",
            path=path,
        )

    from ._winapi import (
        create_file, close_handle, query_allocated_ranges,
        GENERIC_READ, FILE_SHARE_READ, FILE_SHARE_WRITE, OPEN_EXISTING,
    )

    handle = None
    try:
        handle = create_file(
            path,
            access=GENERIC_READ,
            share=FILE_SHARE_READ | FILE_SHARE_WRITE,
            disposition=OPEN_EXISTING,
        )
    except OSError as exc:
        raise WSParseError(str(exc), kind="os", path=path) from exc

    try:
        ranges = query_allocated_ranges(handle, size)
        # Ensure ranges are sorted and non-overlapping
        ranges.sort(key=lambda r: r[0])
        merged = []
        for offset, length in ranges:
            if merged and offset < merged[-1][0] + merged[-1][1]:
                # Overlap or adjacent - merge
                prev_off, prev_len = merged[-1]
                new_end = max(prev_off + prev_len, offset + length)
                merged[-1] = (prev_off, new_end - prev_off)
            else:
                merged.append((offset, length))
        return merged
    except OSError as exc:
        raise WSParseError(str(exc), kind="os", path=path) from exc
    finally:
        if handle is not None:
            close_handle(handle)

"""Sparse-attribute handling."""

import os
import stat

from ._winapi import SPARSE_ATTRIBUTE, is_windows
from .errors import WSParseError


def sparse_state(path):
    """Return ``True`` when ``path`` currently carries the sparse attribute."""
    path = os.fspath(path)

    if not is_windows():
        raise WSParseError(
            "sparse_state requires Windows/NTFS",
            kind="unsupported",
            path=path,
        )

    try:
        info = os.stat(path)
    except OSError as exc:
        raise WSParseError(str(exc), kind="os", path=path) from exc

    if stat.S_ISDIR(info.st_mode):
        raise WSParseError(
            "path is a directory, not a file",
            kind="unsupported",
            path=path,
        )

    attributes = getattr(info, "st_file_attributes", 0)
    return bool(attributes & SPARSE_ATTRIBUTE)


def sparse_flag(path, enabled=True):
    """Turn the sparse attribute of ``path`` on or off.

    ``enabled`` defaults to ``True``.  Returns the state the file ends up in.

    Note: On NTFS, once a file has been extended with actual data (dense),
    setting the sparse flag afterwards does not deallocate existing clusters.
    The flag only affects future writes. This function will set the flag but
    disk_usage() will still reflect the actual allocated clusters.
    """
    path = os.fspath(path)

    if not os.path.exists(path):
        raise WSParseError("no such file: %s" % path, kind="os", path=path)

    if not is_windows():
        raise WSParseError(
            "the sparse attribute is a Windows file-system concept",
            kind="unsupported",
            path=path,
        )

    # Check if it's a directory
    try:
        st = os.stat(path)
    except OSError as exc:
        raise WSParseError(str(exc), kind="os", path=path) from exc

    if stat.S_ISDIR(st.st_mode):
        raise WSParseError(
            "path is a directory, not a file",
            kind="unsupported",
            path=path,
        )

    if not enabled:
        raise WSParseError(
            "clearing the sparse attribute is not implemented yet",
            kind="unsupported",
            path=path,
        )

    # Set the sparse flag using FSCTL_SET_SPARSE
    from ._winapi import (
        create_file, close_handle, set_sparse,
        GENERIC_READ, GENERIC_WRITE, OPEN_EXISTING,
    )

    handle = None
    try:
        handle = create_file(path, disposition=OPEN_EXISTING)
    except OSError as exc:
        raise WSParseError(str(exc), kind="os", path=path) from exc

    try:
        try:
            set_sparse(handle)
        except OSError as exc:
            raise WSParseError(
                "cannot set sparse flag: %s" % exc,
                kind="unsupported",
                path=path,
            ) from exc
        return sparse_state(path)
    finally:
        if handle is not None:
            close_handle(handle)
